/* Minimal ISO BMFF muxer for VideoEncoder AVC samples (no audio). */
globalThis.MP4Mux=(()=>{const enc=new TextEncoder(),join=(...a)=>{const b=new Uint8Array(a.reduce((s,v)=>s+v.length,0));let n=0;for(const v of a){b.set(v,n);n+=v.length;}return b;},u32=n=>new Uint8Array([n>>>24,n>>>16,n>>>8,n]),u16=n=>new Uint8Array([n>>>8,n]),str=s=>enc.encode(s),zero=n=>new Uint8Array(n),box=(t,...a)=>{const d=join(...a);return join(u32(d.length+8),str(t),d);},full=(t,v,f,...a)=>box(t,new Uint8Array([v,f>>>16,f>>>8,f]),...a),matrix=()=>join(u32(65536),u32(0),u32(0),u32(0),u32(65536),u32(0),u32(0),u32(0),u32(0x40000000));
return {build(samples,description,width,height,fps){if(!description||!samples.length)throw Error('Encoder tidak menghasilkan konfigurasi AVC.');const duration=samples.length,ftyp=box('ftyp',str('isom'),u32(512),str('isomiso2avc1mp41'));
const mvhd=full('mvhd',0,0,u32(0),u32(0),u32(fps),u32(duration),u32(65536),u16(256),zero(10),matrix(),zero(24),u32(2));
const tkhd=full('tkhd',0,7,u32(0),u32(0),u32(1),u32(0),u32(duration),zero(8),u16(0),u16(0),u16(0),u16(0),matrix(),u32(width*65536),u32(height*65536));
const mdhd=full('mdhd',0,0,u32(0),u32(0),u32(fps),u32(duration),u16(0x55c4),u16(0)),hdlr=full('hdlr',0,0,u32(0),str('vide'),zero(12),str('Precise Video\0'));
const avc1=box('avc1',zero(6),u16(1),zero(16),u16(width),u16(height),u32(0x00480000),u32(0x00480000),u32(0),u16(1),zero(32),u16(24),u16(65535),box('avcC',new Uint8Array(description)));
const stsd=full('stsd',0,0,u32(1),avc1),stts=full('stts',0,0,u32(1),u32(duration),u32(1)),stsc=full('stsc',0,0,u32(1),u32(1),u32(duration),u32(1)),stsz=full('stsz',0,0,u32(0),u32(duration),...samples.map(s=>u32(s.data.length))),stco=full('stco',0,0,u32(1),u32(ftyp.length+8));const keys=samples.map((s,i)=>s.key?i+1:0).filter(Boolean),stss=full('stss',0,0,u32(keys.length),...keys.map(u32));
const stbl=box('stbl',stsd,stts,stsc,stsz,stco,stss),dinf=box('dinf',full('dref',0,0,u32(1),full('url ',0,1))),minf=box('minf',full('vmhd',0,1,zero(8)),dinf,stbl),moov=box('moov',mvhd,box('trak',tkhd,box('mdia',mdhd,hdlr,minf)));const size=samples.reduce((n,s)=>n+s.data.length,0);return new Blob([ftyp,u32(size+8),str('mdat'),...samples.map(s=>s.data),moov],{type:'video/mp4'});}};
})();
